import "reflect-metadata";
import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Module,
  NotFoundException,
  Param,
  Post,
  Put,
} from "@nestjs/common";
import { NestFactory } from "@nestjs/core";

@Controller("items")
class ItemsController {
  private items: { id: number; name: string }[] = [];
  private nextId = 1;

  @Get()
  findAll() {
    return this.items;
  }

  @Post()
  create(@Body() body: { name: string }) {
    if (!body.name || typeof body.name !== "string" || !body.name.trim()) {
      throw new BadRequestException("name is required and must be a non-empty string");
    }
    const item = { id: this.nextId++, name: body.name.trim() };
    this.items.push(item);
    return item;
  }

  @Get(":id")
  findOne(@Param("id") id: string) {
    const item = this.items.find((i) => i.id === parseInt(id, 10));
    if (!item) {
      throw new NotFoundException("item not found");
    }
    return item;
  }

  @Put(":id")
  update(@Param("id") id: string, @Body() body: { name: string }) {
    if (!body.name || typeof body.name !== "string" || !body.name.trim()) {
      throw new BadRequestException("name is required and must be a non-empty string");
    }
    const item = this.items.find((i) => i.id === parseInt(id, 10));
    if (!item) {
      throw new NotFoundException("item not found");
    }
    item.name = body.name.trim();
    return item;
  }
}

@Module({ controllers: [ItemsController] })
class AppModule {}

async function bootstrap() {
  const app = await NestFactory.create(AppModule, { logger: false });
  await app.listen(8025);
}
bootstrap();
